package com.steglab;
import java.io.IOException;import java.util.concurrent.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.stereotype.Component;
@Component public class RateLimitFilter implements Filter{private final ConcurrentHashMap<String,Deque<Long>> hits=new ConcurrentHashMap<>();public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{var h=(HttpServletRequest)req;var r=(HttpServletResponse)res;if(!h.getRequestURI().startsWith("/api/")){chain.doFilter(req,res);return;}var now=System.currentTimeMillis();var q=hits.computeIfAbsent(h.getRemoteAddr(),k->new ConcurrentLinkedDeque<>());while(!q.isEmpty()&&now-q.peekFirst()>60000)q.pollFirst();if(q.size()>=60){r.setStatus(429);r.setContentType("application/json");r.getWriter().write("{\"detail\":\"Too many requests. Please try again shortly.\"}");return;}q.addLast(now);chain.doFilter(req,res);}}
